macro.command:
if (args?.[0]?.macroPass !== 'postActiveEffects') return;
if (!workflow.failedSaves?.size) return;
const RADIUS = 30, TEMP = 5;
const me = token;
const ftBetween = (a, b) => canvas.grid.measurePath ? canvas.grid.measurePath([a, b]).distance : (Math.hypot(b.x - a.x, b.y - a.y) / canvas.dimensions.size) * canvas.dimensions.distance;
const allies = canvas.tokens.placeables.filter(t => t.id !== me.id && t.actor && t.document.disposition === me.document.disposition && ftBetween(me.center, t.center) <= RADIUS);
for (const ally of allies) {
  const cur = ally.actor.system.attributes.hp.temp ?? 0;
  await ally.actor.update({ 'system.attributes.hp.temp': Math.max(cur, TEMP) });
}
